    43	                .orElseThrow(() -> new HotelException(
    44	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
    45	        if (request.guests() > room.capacity()) {
    46	            throw new HotelException(
