   125	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
   126	            throw notAllowed(reservation, "check out");
   127	        }
   128	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
   129	        return new ReservationReceipt(reservation, roomOf(reservation));
   130	    }
